{"upserts": [{"dependencies": ["inventory-core"], "name": "Inventory Expiry", "pluginId": "inventory-expiry", "sourceFiles": {"client.tsx": "import { useCallback, useEffect, useMemo, useState, type FormEvent } from "react";
