  readonly batchNo: string;
  readonly quantity: number;
  readonly expiryDate: string;
  readonly note?: string;
}

export interface ExpirySummary {
  readonly windowDays: number;
  readonly criticalDays: number;
  readonly expiredCount: number;
  readonly criticalCount: number;
  readonly warningCount: number;
  readonly nearExpiryCount: number;
  readonly trackedBatchCount: number;
  readonly trackedQuantity: number;
}

export interface ExpiryOverview {
  readonly summary: ExpirySummary;
  readonly alerts: readonly ExpiryBatchView[];
  readonly batches: readonly ExpiryBatchView[];
}

export interface InventoryExpiryService {
  listBatches(
    itemId?: string,
    windowDays?: number,
    criticalDays?: number,
  ): ExpiryBatchView[];
  registerBatch(input: RegisterExpiryBatchInput): ExpiryBatchView;
  writeOffBatch(id: string, reason?: string): ExpiryBatchView;
  removeBatch(id: string): boolean;
  overview(windowDays?: number, criticalDays?: number): ExpiryOverview;
}

