function ExpiryItemBadges({ item }: InventoryItemSlotProps) {
  const { batches } = useExpiry(30);
  const mine = useMemo(
    () =>
      batches.filter(
        (batch) => batch.itemId === item.id && batch.quantity > 0,
      ),
    [batches, item.id],
  );
  if (mine.length === 0) return null;
  const nearest = mine.reduce(
    (acc, batch) => (batch.daysUntilExpiry < acc.daysUntilExpiry ? batch : acc),
    mine[0],
  );
  return (
    <span
      data-expiry-badge={item.sku}
      className={`rounded border px-1.5 py-0.5 text-[11px] font-medium ${statusTone(
        nearest.status,
      )}`}
    >
      {nearest.status === "ok"
        ? `效期 ${nearest.expiryDate}`
        : `${statusLabel(nearest.status)} · ${formatDays(nearest.daysUntilExpiry)}`}
    </span>
  );
}

function ExpiryItemDetail({ item }: InventoryItemSlotProps) {
  const { batches, reload } = useExpiry(30);
  const [open, setOpen] = useState(false);
  const [batchNo, setBatchNo] = useState("");
  const [quantity, setQuantity] = useState("10");
  const [expiryDate, setExpiryDate] = useState(() => isoDateFromToday(90));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const mine = useMemo(
    () => batches.filter((batch) => batch.itemId === item.id),
    [batches, item.id],
  );
  const registered = mine.reduce((sum, batch) => sum + batch.quantity, 0);
  const uncovered = Math.max(0, item.quantity - registered);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await requestJson<{ batch: ExpiryBatchView }>(
        "/api/app/inventory-expiry/batches",
        {
          method: "POST",
          body: JSON.stringify({
            itemId: item.id,
            batchNo: batchNo.trim(),
            quantity: Number(quantity) || 0,
            expiryDate,
          }),
        },
      );
      setBatchNo("");
      setOpen(false);
      await reload();
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      data-expiry-detail={item.sku}
      className="mt-2 border-t border-line pt-2 text-xs text-muted"
    >
      <div className="flex flex-wrap items-center gap-2">
        <span>
          效期批次 {mine.length} 个 · 已登记 {registered} {item.unit} · 未登记{" "}
          {uncovered} {item.unit}
        </span>
        <button
          type="button"
          data-expiry-toggle={item.sku}
          onClick={() => setOpen((prev) => !prev)}
          className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] font-medium text-ink hover:bg-line/40"
        >
          {open ? "收起效期登记" : "登记效期批次"}
        </button>
      </div>

      {mine.length > 0 && (
        <ul className="mt-1.5 space-y-1">
          {mine.map((batch) => (
            <li
              key={batch.id}
              data-expiry-row={batch.batchNo}
              className="flex flex-wrap items-center gap-2"
            >
              <span className="font-mono text-ink">{batch.batchNo}</span>
              <span>余 {batch.quantity}</span>
              <span>{batch.expiryDate}</span>
              <span
                className={`rounded border px-1.5 py-0.5 text-[11px] ${statusTone(
                  batch.status,
