", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  ExpiryBatchView,
  ExpiryOverview,
  ExpiryStatus,
  ExpirySummary,
  InventoryExpiryService,
  RegisterExpiryBatchInput,
} from "./contract.d.ts";

const DAY_MS = 86_400_000;
const DEFAULT_WINDOW_DAYS = 30;
const DEFAULT_CRITICAL_DAYS = 7;
const MAX_WINDOW_DAYS = 3650;

const SELECT_COLUMNS = `id, item_id, batch_no, quantity, expiry_date, note, created_at, updated_at`;

interface CoreInventoryItem {
  readonly id: string;
  readonly sku: string;
  readonly name: string;
  readonly quantity: number;
  readonly unit: string;
}

interface CoreInventoryService {
  list(): CoreInventoryItem[];
  get(id: string): CoreInventoryItem | null;
}

interface ExpiryBatchRow {
  readonly id: string;
  readonly item_id: string;
  readonly batch_no: string;
  readonly quantity: number;
  readonly expiry_date: string;
  readonly note: string | null;
  readonly created_at: string;
  readonly updated_at: string;
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

/**
 * inventory-core 暴露的只读库存服务端口。依赖会保证它在插件就绪后才可用。
 */
function coreInventory(ctx: Context): CoreInventoryService | undefined {
  return (ctx as unknown as { inventory?: CoreInventoryService }).inventory;
}

function startOfTodayUtc(): number {
  const now = new Date();
  return Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
}

function parseDateOnly(value: string): number | null {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const parts = value.split("-").map((part) => Number.parseInt(part, 10));
  const year = parts[0];
  const month = parts[1];
  const day = parts[2];
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) {
    return null;
  }
  const timestamp = Date.UTC(year, month - 1, day);
  const parsed = new Date(timestamp);
  if (
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() !== month - 1 ||
    parsed.getUTCDate() !== day
  ) {
    return null;
  }
  return timestamp;
}

function daysUntil(expiryDate: string): number {
  const timestamp = parseDateOnly(expiryDate);
  if (timestamp === null) return 0;
  return Math.round((timestamp - startOfTodayUtc()) / DAY_MS);
}

function classify(
  days: number,
  windowDays: number,
  criticalDays: number,
): ExpiryStatus {
  if (days < 0) return "expired";
  if (days <= criticalDays) return "critical";
  if (days <= windowDays) return "warning";
  return "ok";
}

function readInt(
  raw: string | undefined,
  fallback: number,
  max = MAX_WINDOW_DAYS,
): number {
  if (typeof raw !== "string" || raw.trim().length === 0) return fallback;
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(Math.max(0, parsed), max);
}

function toErrorResponse(error: unknown): {
  status: number;
  body: { error: string };
} {
  const status =
    typeof (error as { status?: unknown })?.status === "number"
      ? (error as { status: number }).status
      : 400;
  return {
    status,
    body: { error: error instanceof Error ? error.message : String(error) },
  };
}

export default class InventoryExpiryServiceImpl
  extends Service
  implements InventoryExpiryService
{
  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "inventoryExpiry");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_inventory_expiry__batches (
        id TEXT PRIMARY KEY,
        item_id TEXT NOT NULL,
        batch_no TEXT NOT NULL,
        quantity INTEGER NOT NULL DEFAULT 0,
        expiry_date TEXT NOT NULL,
        note TEXT,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL,
        UNIQUE (item_id, batch_no)
      )
    `);
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS plg_inventory_expiry__batches_expiry
      ON plg_inventory_expiry__batches (item_id, expiry_date)
    `);

    ctx.http.route("GET", "/overview", (req) => {
      const windowDays = readInt(req.query.windowDays, DEFAULT_WINDOW_DAYS);
      const criticalDays = Math.min(
        readInt(req.query.criticalDays, DEFAULT_CRITICAL_DAYS),
        windowDays,
      );
      return this.overview(windowDays, criticalDays);
    });

    ctx.http.route("GET", "/batches", (req) => {
      const windowDays = readInt(req.query.windowDays, DEFAULT_WINDOW_DAYS);
      const criticalDays = Math.min(
        readInt(req.query.criticalDays, DEFAULT_CRITICAL_DAYS),
        windowDays,
      );
      const itemId =
        typeof req.query.itemId === "string" && req.query.itemId.length > 0
          ? req.query.itemId
          : undefined;
      const batches = this.listBatches(itemId, windowDays, criticalDays);
      return {
        batches,
        summary: this.buildSummary(batches, windowDays, criticalDays),
      };
    });

    ctx.http.route("GET", "/items/:itemId/batches", (req) => {
      const windowDays = readInt(req.query.windowDays, DEFAULT_WINDOW_DAYS);
      const criticalDays = Math.min(
        readInt(req.query.criticalDays, DEFAULT_CRITICAL_DAYS),
        windowDays,
      );
      const itemId = req.params.itemId;
      const inventory = coreInventory(ctx);
      if (inventory && !inventory.get(itemId)) {
        return {
          status: 404,
          body: { error: `Inventory item not found: ${itemId}` },
        };
      }
      const batches = this.listBatches(itemId, windowDays, criticalDays);
      return {
        batches,
        summary: this.buildSummary(batches, windowDays, criticalDays),
      };
    });

    ctx.http.route("POST", "/batches", (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        const batch = this.registerBatch({
          itemId: typeof body.itemId === "string" ? body.itemId : "",
          batchNo: typeof body.batchNo === "string" ? body.batchNo : "",
          quantity:
            typeof body.quantity === "number" ? body.quantity : Number.NaN,
          expiryDate:
            typeof body.expiryDate === "string" ? body.expiryDate : "",
          note: typeof body.note === "string" ? body.note : undefined,
        });
        return { status: 201, body: { batch } };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("POST", "/batches/:id/write-off", (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        const batch = this.writeOffBatch(
          req.params.id,
          typeof body.reason === "string" ? body.reason : undefined,
        );
        return { batch };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("DELETE", "/batches/:id", (req) => {
      try {
        const removed = this.removeBatch(req.params.id);
        if (!removed) {
          return {
            status: 404,
            body: { error: `Expiry batch not found: ${req.params.id}` },
          };
        }
        return { deleted: true, id: req.params.id };
      } catch (error) {
        return toErrorResponse(error);
      }
    });
  }

  listBatches(
    itemId?: string,
    windowDays: number = DEFAULT_WINDOW_DAYS,
    criticalDays: number = DEFAULT_CRITICAL_DAYS,
  ): ExpiryBatchView[] {
    this.reconcileInventoryBatches();
    const rows = itemId ? this.rowsForItem(itemId) : this.allRows();
    const items = new Map<string, CoreInventoryItem>();
    const inventory = coreInventory(this.ctx);
    if (inventory) {
      try {
        for (const item of inventory.list()) items.set(item.id, item);
      } catch {
        // 库存服务暂不可用时仍可读取本插件自己的批次数据（不参与跨插件写入）
      }
    }
    return rows.map((row) =>
      this.toView(row, items.get(row.item_id), windowDays, criticalDays),
    );
  }

  registerBatch(input: RegisterExpiryBatchInput): ExpiryBatchView {
    const inventory = coreInventory(this.ctx);
    const itemId = typeof input.itemId === "string" ? input.itemId : "";
    const item = itemId.length > 0 ? inventory?.get(itemId) ?? null : null;
    if (!item) {
      throw httpError(404, `Inventory item not found: ${itemId || "(missing)"}`);
    }

    const batchNo = typeof input.batchNo === "string" ? input.batchNo.trim() : "";
    if (batchNo.length === 0) throw httpError(400, "Batch number is required");

    const quantity = Math.trunc(input.quantity);
    if (!Number.isFinite(quantity) || quantity <= 0) {
      throw httpError(400, "Batch quantity must be a positive integer");
    }

    const expiryDate =
      typeof input.expiryDate === "string" ? input.expiryDate.trim() : "";
    if (parseDateOnly(expiryDate) === null) {
      throw httpError(400, "Expiry date must be a valid YYYY-MM-DD date");
    }

    const duplicate = this.db
      .prepare(
        `SELECT id FROM plg_inventory_expiry__batches WHERE item_id = ? AND batch_no = ?`,
      )
      .get<{ id: string }>(item.id, batchNo);
    if (duplicate) {
      throw httpError(409, `Batch ${batchNo} already exists for SKU ${item.sku}`);
    }

    this.reconcileInventoryBatches();
    const tracked = this.trackedQuantity(item.id);
    if (tracked + quantity > item.quantity) {
      throw httpError(
        409,
        `Batch quantity exceeds tracked stock for ${item.sku}: stock ${item.quantity}, already registered ${tracked}`,
      );
    }

    const id = `exp_${Date.now().toString(36)}_${Math.random()
      .toString(36)
      .slice(2, 8)}`;
    const now = new Date().toISOString();
    const note =
      typeof input.note === "string" && input.note.trim().length > 0
        ? input.note.trim()
        : null;
    this.db
      .prepare(
        `INSERT INTO plg_inventory_expiry__batches
           (id, item_id, batch_no, quantity, expiry_date, note, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
      )
      .run(id, item.id, batchNo, quantity, expiryDate, note, now, now);

    return this.toView(
      this.rowById(id)!,
      item,
      DEFAULT_WINDOW_DAYS,
      DEFAULT_CRITICAL_DAYS,
    );
  }

  writeOffBatch(id: string, reason?: string): ExpiryBatchView {
    const row = this.rowById(id);
    if (!row) throw httpError(404, `Expiry batch not found: ${id}`);

    const now = new Date().toISOString();
    const note =
      typeof reason === "string" && reason.trim().length > 0
        ? `${reason.trim()} (write-off ${now})`
        : `write-off ${now}`;
    this.db
      .prepare(
        `UPDATE plg_inventory_expiry__batches
         SET quantity = 0, note = ?, updated_at = ?
         WHERE id = ?`,
      )
      .run(note, now, id);

    const inventory = coreInventory(this.ctx);
    const item = inventory ? inventory.get(row.item_id) : null;
    return this.toView(
      this.rowById(id)!,
      item,
      DEFAULT_WINDOW_DAYS,
      DEFAULT_CRITICAL_DAYS,
    );
  }

  removeBatch(id: string): boolean {
    const result = this.db
      .prepare(`DELETE FROM plg_inventory_expiry__batches WHERE id = ?`)
      .run(id);
    return Number(result.changes) > 0;
  }

  overview(
    windowDays: number = DEFAULT_WINDOW_DAYS,
    criticalDays: number = DEFAULT_CRITICAL_DAYS,
  ): ExpiryOverview {
    const batches = this.listBatches(undefined, windowDays, criticalDays);
    const alerts = batches.filter(
      (batch) => batch.quantity > 0 && batch.status !== "ok",
    );
    return {
      summary: this.buildSummary(batches, windowDays, criticalDays),
      alerts,
      batches,
    };
  }

  private buildSummary(
    batches: readonly ExpiryBatchView[],
    windowDays: number,
    criticalDays: number,
  ): ExpirySummary {
    const live = batches.filter((batch) => batch.quantity > 0);
    const alerts = live.filter((batch) => batch.status !== "ok");
    return {
      windowDays,
      criticalDays,
      expiredCount: alerts.filter((batch) => batch.status === "expired").length,
      criticalCount: alerts.filter((batch) => batch.status === "critical")
        .length,
      warningCount: alerts.filter((batch) => batch.status === "warning").length,
      nearExpiryCount: alerts.length,
      trackedBatchCount: live.length,
      trackedQuantity: live.reduce((sum, batch) => sum + batch.quantity, 0),
    };
  }

  private toView(
    row: ExpiryBatchRow,
    item: CoreInventoryItem | null | undefined,
    windowDays: number,
    criticalDays: number,
  ): ExpiryBatchView {
    const days = daysUntil(row.expiry_date);
    return {
      id: row.id,
      itemId: row.item_id,
      batchNo: row.batch_no,
      quantity: Number(row.quantity),
      expiryDate: row.expiry_date,
      note: row.note ?? null,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
      itemSku: item?.sku ?? null,
      itemName: item?.name ?? null,
      daysUntilExpiry: days,
      status: classify(days, windowDays, criticalDays),
    };
  }

  private allRows(): ExpiryBatchRow[] {
    return this.db
      .prepare(
        `SELECT ${SELECT_COLUMNS} FROM plg_inventory_expiry__batches
         ORDER BY expiry_date ASC, item_id ASC, batch_no ASC`,
      )
      .all<ExpiryBatchRow>();
  }

  private rowsForItem(itemId: string): ExpiryBatchRow[] {
    return this.db
      .prepare(
        `SELECT ${SELECT_COLUMNS} FROM plg_inventory_expiry__batches
         WHERE item_id = ?
         ORDER BY expiry_date ASC, batch_no ASC`,
      )
      .all<ExpiryBatchRow>(itemId);
  }

  private rowById(id: string): ExpiryBatchRow | undefined {
    return this.db
      .prepare(
        `SELECT ${SELECT_COLUMNS} FROM plg_inventory_expiry__batches WHERE id = ?`,
      )
      .get<ExpiryBatchRow>(id);
  }

  private trackedQuantity(itemId: string): number {
    const row = this.db
      .prepare(
        `SELECT COALESCE(SUM(quantity), 0) AS total
         FROM plg_inventory_expiry__batches WHERE item_id = ?`,
      )
      .get<{ total: number }>(itemId);
    return Number(row?.total ?? 0);
  }

  /**
   * 把批次余量与 inventory-core 的库存数量对齐：库存下降时按 FEFO 消耗批次。
   * 已过期批次视为隔离库存，必须通过核销出账，不参与自动消耗。
   * 只在读取时校准，绝不写入 inventory-core 的表。
   */
  private reconcileInventoryBatches(): void {
    const inventory = coreInventory(this.ctx);
    if (!inventory) return;
    let items: CoreInventoryItem[];
    try {
      items = inventory.list();
    } catch {
      return;
    }
    for (const item of items) {
      this.reconcileItem(item.id, item.quantity);
    }
  }

  private reconcileItem(itemId: string, itemQuantity: number): void {
    const rows = this.rowsForItem(itemId);
    let excess =
      rows.reduce((sum, row) => sum + Number(row.quantity), 0) -
      Math.max(0, Math.trunc(itemQuantity));
    if (excess <= 0) return;

    const statement = this.db.prepare(
      `UPDATE plg_inventory_expiry__batches
       SET quantity = ?, updated_at = ?
       WHERE id = ?`,
    );
    const now = new Date().toISOString();
    this.db.transaction(() => {
      for (const row of rows) {
        if (excess <= 0) break;
        const quantity = Number(row.quantity);
        if (quantity <= 0) continue;
        if (daysUntil(row.expiry_date) < 0) continue;
        const consumed = Math.min(quantity, excess);
        excess -= consumed;
        statement.run(quantity - consumed, now, row.id);
      }
    });
  }
}
