  assert.equal(summary.expiredCount, 1);
  assert.equal(summary.criticalCount, 1);
  assert.equal(summary.nearExpiryCount, 2);
  assert.equal(summary.trackedBatchCount, 2);
  assert.equal(summary.trackedQuantity, 9);
  assert.deepEqual(
    (overview.body as { alerts: BatchView[] }).alerts.map(
      (batch) => batch.batchNo,
    ),
    ["B-EXPIRED", "B-SOON"],
  );

  // inventory-core 依旧是库存真相：出库后剩余批次按 FEFO 对齐（过期批次隔离）
  const stocked = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemId}/stock`,
    body: { delta: -5 },
  });
  expectStatus(stocked, 200, "stock out via inventory-core");
  assert.equal((stocked.body as { item: { quantity: number } }).item.quantity, 7);

  const afterStock = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/items/${itemId}/batches`,
  });
  expectStatus(afterStock, 200, "item batches after stock out");
  const afterBatches = (afterStock.body as { batches: BatchView[] }).batches;
  const byBatchNo = new Map(
    afterBatches.map((batch) => [batch.batchNo, batch] as const),
  );
  assert.equal(byBatchNo.get("B-SOON")?.quantity, 3);
  assert.equal(byBatchNo.get("B-EXPIRED")?.quantity, 4);
  assert.equal(
    afterBatches.reduce((sum, batch) => sum + batch.quantity, 0),
    7,
  );

  const expiredId = byBatchNo.get("B-EXPIRED")!.id;
  const writeOff = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-expiry/batches/${expiredId}/write-off`,
    body: { reason: "过期报废" },
  });
  expectStatus(writeOff, 200, "write off expired batch");
  assert.equal((writeOff.body as { batch: BatchView }).batch.quantity, 0);

  const afterWriteOff = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-expiry/overview",
    query: { windowDays: "30" },
  });
  expectStatus(afterWriteOff, 200, "overview after write-off");
  const afterSummary = (afterWriteOff.body as { summary: SummaryView }).summary;
  assert.equal(afterSummary.expiredCount, 0);
  assert.equal(afterSummary.nearExpiryCount, 1);
  assert.equal(afterSummary.trackedQuantity, 3);

  const soonId = byBatchNo.get("B-SOON")!.id;
  const removed = await ctx.request({
    method: "DELETE",
    path: `/api/app/inventory-expiry/batches/${soonId}`,
  });
  expectStatus(removed, 200, "delete batch");
  assert.equal((removed.body as { deleted: boolean }).deleted, true);

  const finalBatches = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-expiry/items/${itemId}/batches`,
  });
  expectStatus(finalBatches, 200, "final batch list");
  const kept = (finalBatches.body as { batches: BatchView[] }).batches;
  assert.equal(kept.length, 1);
  assert.equal(kept[0].batchNo, "B-EXPIRED");
  assert.equal(kept[0].quantity, 0);

  // inventory-core 原有功能保持可用
  const coreItem = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-core/items/${itemId}`,
  });
  expectStatus(coreItem, 200, "read inventory item");
  const coreItemBody = (coreItem.body as { item: { sku: string; quantity: number } })
    .item;
  assert.equal(coreItemBody.sku, "EXP-TEST-1");
  assert.equal(coreItemBody.quantity, 7);
}
