    >
      <span>
        出库审批：单次出库超过 <b className="text-ink">{policy.threshold}</b>{" "}
        件需填写审批理由，否则由审批插件拦截
      </span>
      <span className="text-[11px] opacity-80">
        待审批 {summary.pendingCount} 单 · 已拦截 {summary.blockedCount} 次
      </span>
    </div>
  );
}

function ApprovalItemBadge({ item }: InventoryItemSlotProps) {
  const { requests } = useApproval();
  const pending = useMemo(
    () =>
      requests.filter(
        (request) => request.itemId === item.id && request.status === "pending",
      ).length,
    [requests, item.id],
  );
  if (pending === 0) return null;
  return (
    <span
      data-approval-badge={item.sku}
      className="rounded border border-danger/40 bg-danger/10 px-1.5 py-0.5 text-[11px] font-medium text-danger"
    >
      待审批 {pending}
    </span>
  );
}

function SummaryCard(props: {
  readonly label: string;
  readonly value: number;
  readonly tone: string;
}) {
  return (
    <div className={`rounded-lg border px-3 py-2 ${props.tone}`}>
      <div className="text-[11px] opacity-80">{props.label}</div>
      <div className="font-mono text-lg font-semibold">{props.value}</div>
    </div>
  );
}

function ApprovalPage() {
  const navigate = useNavigate();
  const { policy, summary, requests, audit, loading, error, reload } =
    useApproval();

  const [items, setItems] = useState<InventoryItemSummary[]>([]);
  const [itemId, setItemId] = useState("");
  const [quantity, setQuantity] = useState("60");
  const [reason, setReason] = useState("");
  const [thresholdInput, setThresholdInput] = useState(String(policy.threshold));
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState("");
  const [hint, setHint] = useState("");

  const loadItems = useCallback(async () => {
    try {
      const data = await requestJson<{ items: InventoryItemSummary[] }>(
        "/api/app/inventory-core/items",
      );
      setItems(data.items ?? []);
    } catch {
      setItems([]);
    }
  }, []);

  useEffect(() => {
    void loadItems();
  }, [loadItems]);

  useEffect(() => {
    setThresholdInput(String(policy.threshold));
  }, [policy.threshold]);

  const pending = useMemo(
    () => requests.filter((request) => request.status === "pending"),
    [requests],
  );
  const selectedItem = items.find((item) => item.id === itemId);

  const submitRequest = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    if (!itemId) {
      setFormError("请选择需要出库的商品");
      return;
    }
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{ request: ApprovalRequestView }>(
        "/api/app/inventory-approval/requests",
        {
          method: "POST",
          body: JSON.stringify({
            itemId,
            quantity: Number(quantity) || 0,
            reason: reason.trim(),
          }),
        },
      );
      setReason("");
      setHint(`审批单 ${data.request.code} 已提交，等待审批`);
      await reload();
      await loadItems();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const approve = async (request: ApprovalRequestView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{
        request: ApprovalRequestView;
        item: InventoryItemSummary;
      }>(
        `/api/app/inventory-approval/requests/${encodeURIComponent(
          request.id,
        )}/approve`,
        { method: "POST", body: JSON.stringify({ approver: "出库审批工作台" }) },
      );
      setHint(
        `审批单 ${data.request.code} 已通过，出库 ${data.request.quantity} ${data.item.unit}`,
      );
      await reload();
      await loadItems();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const reject = async (request: ApprovalRequestView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{ request: ApprovalRequestView }>(
        `/api/app/inventory-approval/requests/${encodeURIComponent(
          request.id,
        )}/reject`,
        {
          method: "POST",
          body: JSON.stringify({ note: "出库审批工作台驳回" }),
        },
      );
      setHint(`审批单 ${data.request.code} 已驳回`);
      await reload();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const saveThreshold = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    const value = Number(thresholdInput);
    if (!Number.isFinite(value)) {
      setFormError("审批阈值必须是数字");
      return;
    }
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{ policy: ApprovalPolicy }>(
        "/api/app/inventory-approval/policy",
        { method: "PUT", body: JSON.stringify({ threshold: value }) },
      );
      setHint(`审批阈值已更新为 ${data.policy.threshold} 件`);
      await reload();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div data-approval-page="true" className="mx-auto max-w-4xl p-6 text-ink">
      <header className="mb-4 flex flex-wrap items-center justify-between gap-3 border-b border-line pb-3">
        <div>
          <h1 className="text-lg font-semibold">出库审批</h1>
          <p className="text-xs text-muted">
            单次出库超过 {policy.threshold} 件必须填写审批理由，通过后可自动出库
          </p>
        </div>
        <button
          type="button"
          data-approval-back="true"
          onClick={() => navigate("/")}
          className="rounded-md border border-line bg-surface px-3 py-1.5 text-xs font-medium text-ink hover:bg-canvas"
        >
          返回库存
        </button>
      </header>

      {(error || formError) && (
        <div
          role="alert"
          data-approval-error="true"
          className="mb-3 rounded-md border border-danger/40 bg-danger/10 px-3 py-2 text-xs text-danger"
        >
          {formError || error}
        </div>
      )}

      {hint && (
        <div
          data-approval-hint="true"
          className="mb-3 rounded-md border border-line bg-surface px-3 py-2 text-xs text-muted"
        >
          {hint}
        </div>
      )}

      <div className="mb-4 grid grid-cols-2 gap-2 sm:grid-cols-4">
        <SummaryCard
          label="待审批"
          value={summary.pendingCount}
          tone="border-danger/40 bg-danger/10 text-danger"
        />
        <SummaryCard
          label="已通过"
          value={summary.approvedCount}
          tone="border-line bg-surface text-ink"
        />
        <SummaryCard
          label="已驳回"
          value={summary.rejectedCount}
          tone="border-line bg-surface text-muted"
        />
        <SummaryCard
          label="被拦截次数"
          value={summary.blockedCount}
          tone="border-line bg-canvas text-muted"
        />
      </div>

      <section className="mb-4 rounded-lg border border-line bg-surface p-3">
        <h2 className="mb-2 text-sm font-semibold">审批阈值</h2>
        <form
          onSubmit={(event) => void saveThreshold(event)}
          data-approval-policy-form="true"
          className="flex flex-wrap items-center gap-2"
        >
          <span className="text-xs text-muted">单次出库大于</span>
          <input
            type="number"
            min={1}
            value={thresholdInput}
            onChange={(event) => setThresholdInput(event.target.value)}
            data-approval-threshold-input="true"
            className="w-24 rounded border border-line bg-canvas px-2 py-1 text-xs text-ink"
          />
          <span className="text-xs text-muted">件需审批</span>
          <button
            type="submit"
            disabled={busy}
            data-approval-threshold-submit="true"
            className="rounded-md border border-line bg-canvas px-2.5 py-1 text-xs font-medium text-ink hover:bg-line/40 disabled:opacity-50"
          >
            保存阈值
          </button>
        </form>
      </section>

      <section className="mb-4 rounded-lg border border-line bg-surface p-3">
        <h2 className="mb-2 text-sm font-semibold">提交出库审批</h2>
        {items.length === 0 ? (
          <p className="text-xs text-muted">
            暂无商品，请先在库存页新增商品后再提交出库审批。
          </p>
        ) : (
          <form
            onSubmit={(event) => void submitRequest(event)}
            data-approval-request-form="true"
            className="flex flex-wrap items-center gap-2"
          >
            <select
              value={itemId}
              onChange={(event) => setItemId(event.target.value)}
              data-approval-item-select="true"
              className="rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            >
              <option value="">选择商品</option>
              {items.map((item) => (
                <option key={item.id} value={item.id}>
                  {item.sku} · {item.name} · 库存 {item.quantity}
                </option>
              ))}
            </select>
            <input
              type="number"
              min={1}
              value={quantity}
              onChange={(event) => setQuantity(event.target.value)}
              placeholder="出库数量"
              data-approval-qty-input="true"
              className="w-24 rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            />
            <input
              type="text"
              value={reason}
              onChange={(event) => setReason(event.target.value)}
              placeholder="审批理由（必填）"
              data-approval-reason-input="true"
              className="min-w-40 flex-1 rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            />
            <button
              type="submit"
              disabled={busy}
              data-approval-submit="true"
              className="rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-surface hover:bg-accent/90 disabled:opacity-50"
            >
              提交审批
            </button>
            {selectedItem && (
              <span className="text-xs text-muted">
                当前库存 {selectedItem.quantity} {selectedItem.unit}
              </span>
            )}
          </form>
        )}
      </section>

      <section className="mb-4 rounded-lg border border-line bg-surface">
        <div className="flex flex-wrap items-center justify-between gap-2 border-b border-line px-3 py-2">
          <h2 className="text-sm font-semibold">待审批出库单</h2>
          <span className="text-xs text-muted">
            {loading ? "加载中…" : `${pending.length} 单待处理`}
          </span>
        </div>
        {pending.length === 0 ? (
          <div className="py-6 text-center text-xs text-muted">
            当前没有待审批的出库申请
          </div>
        ) : (
          <table className="w-full text-left text-xs" data-approval-pending-table="true">
            <thead className="bg-canvas text-muted">
              <tr>
                <th className="px-3 py-1.5 font-medium">审批单</th>
                <th className="px-3 py-1.5 font-medium">商品</th>
                <th className="px-3 py-1.5 font-medium">出库数量</th>
                <th className="px-3 py-1.5 font-medium">审批理由</th>
                <th className="px-3 py-1.5 font-medium">操作</th>
              </tr>
            </thead>
            <tbody>
              {pending.map((request) => (
                <tr
                  key={request.id}
                  data-approval-pending-row={request.code}
                  className="border-t border-line"
                >
                  <td className="px-3 py-1.5 font-mono">{request.code}</td>
                  <td className="px-3 py-1.5">
                    <span className="font-mono text-muted">{request.itemSku}</span>{" "}
                    {request.itemName}
                  </td>
                  <td className="px-3 py-1.5">{request.quantity}</td>
                  <td className="px-3 py-1.5">{request.reason}</td>
                  <td className="px-3 py-1.5">
                    <div className="flex items-center gap-1.5">
                      <button
                        type="button"
                        disabled={busy}
                        data-approval-approve={request.code}
                        onClick={() => void approve(request)}
                        className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] hover:bg-line/40 disabled:opacity-50"
                      >
                        通过并出库
                      </button>
                      <button
                        type="button"
                        disabled={busy}
                        data-approval-reject={request.code}
                        onClick={() => void reject(request)}
                        className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] hover:bg-line/40 disabled:opacity-50"
                      >
                        驳回
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="rounded-lg border border-line bg-surface">
        <div className="flex flex-wrap items-center justify-between gap-2 border-b border-line px-3 py-2">
          <h2 className="text-sm font-semibold">出库审计</h2>
          <span className="text-xs text-muted">
            放行 {summary.allowedCount} 次 · 拦截 {summary.blockedCount} 次
          </span>
        </div>
        {audit.length === 0 ? (
          <div className="py-6 text-center text-xs text-muted">
            暂无大额出库审计记录
          </div>
        ) : (
          <table className="w-full text-left text-xs" data-approval-audit-table="true">
            <thead className="bg-canvas text-muted">
              <tr>
                <th className="px-3 py-1.5 font-medium">时间</th>
                <th className="px-3 py-1.5 font-medium">商品</th>
                <th className="px-3 py-1.5 font-medium">出库数量</th>
                <th className="px-3 py-1.5 font-medium">阈值</th>
                <th className="px-3 py-1.5 font-medium">结果</th>
                <th className="px-3 py-1.5 font-medium">来源</th>
              </tr>
            </thead>
            <tbody>
              {audit.map((entry: ApprovalAuditEntry) => (
                <tr
                  key={entry.id}
                  data-approval-audit-row={entry.id}
                  className="border-t border-line"
                >
                  <td className="px-3 py-1.5 text-muted">
                    {formatTime(entry.createdAt)}
                  </td>
                  <td className="px-3 py-1.5 font-mono">
                    {entry.itemSku ?? entry.itemId}
                  </td>
                  <td className="px-3 py-1.5">{entry.outboundQuantity}</td>
                  <td className="px-3 py-1.5">{entry.threshold}</td>
                  <td className="px-3 py-1.5">
                    <span
                      className={
                        entry.outcome === "blocked"
                          ? "rounded border border-danger/40 bg-danger/10 px-1.5 py-0.5 text-[11px] text-danger"
                          : "rounded border border-line bg-canvas px-1.5 py-0.5 text-[11px] text-muted"
                      }
                    >
                      {entry.outcome === "blocked" ? "已拦截" : "已放行"}
                    </span>
                  </td>
                  <td className="px-3 py-1.5">
                    {entry.source === "approval"
                      ? `审批单 ${entry.approvalCode ?? ""}`
                      : "直接出库"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="mt-4 rounded-lg border border-line bg-surface">
        <div className="border-b border-line px-3 py-2">
          <h2 className="text-sm font-semibold">最近审批单</h2>
        </div>
        {requests.length === 0 ? (
          <div className="py-6 text-center text-xs text-muted">暂无审批单</div>
        ) : (
          <ul className="divide-y divide-line text-xs">
            {requests.slice(0, 8).map((request) => (
              <li
                key={request.id}
                data-approval-history-row={request.code}
                className="flex flex-wrap items-center gap-2 px-3 py-1.5"
              >
                <span className="font-mono text-muted">{request.code}</span>
                <span>{request.itemSku}</span>
                <span>{request.quantity} 件</span>
                <span
                  className={`rounded border px-1.5 py-0.5 text-[11px] ${statusTone(
                    request.status,
                  )}`}
                >
                  {statusLabel(request.status)}
                </span>
                {request.note && (
                  <span className="text-muted">{request.note}</span>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

