      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

async function refreshOverview(force = false): Promise<void> {
  if (inflight) return inflight;
  if (!force && snapshot.overview) return;
  const promise = (async () => {
    publish({ loading: true });
    try {
      const overview = await requestJson<ApprovalOverview>(
        "/api/app/inventory-approval/overview",
      );
      publish({ overview, loading: false, error: "" });
    } catch (err) {
      publish({
        loading: false,
        error: err instanceof Error ? err.message : String(err),
      });
    }
  })();
  inflight = promise;
  try {
    await promise;
  } finally {
    inflight = null;
  }
}

function useApproval() {
  const [state, setState] = useState<ApprovalSnapshot>(snapshot);

  useEffect(() => {
    const listener = (next: ApprovalSnapshot) => setState(next);
    listeners.add(listener);
    setState(snapshot);
    void refreshOverview();
    return () => {
      listeners.delete(listener);
    };
  }, []);

  const reload = useCallback(() => refreshOverview(true), []);

  return {
    policy: state.overview?.policy ?? EMPTY_POLICY,
    summary: state.overview?.summary ?? EMPTY_SUMMARY,
    requests: state.overview?.requests ?? [],
    audit: state.overview?.audit ?? [],
    loading: state.loading,
    error: state.error,
    reload,
  };
}

function statusLabel(status: ApprovalStatus): string {
  switch (status) {
    case "approved":
      return "已通过";
    case "rejected":
      return "已驳回";
    default:
      return "待审批";
  }
}

function statusTone(status: ApprovalStatus): string {
  switch (status) {
    case "approved":
      return "border-line bg-canvas text-ink";
    case "rejected":
      return "border-danger/40 bg-danger/10 text-danger";
    default:
      return "border-line bg-surface text-muted";
  }
}

function formatTime(value: string): string {
  return value.replace("T", " ").slice(0, 19);
}

function ApprovalHeaderAction() {
  const navigate = useNavigate();
  const { summary } = useApproval();
  const count = summary.pendingCount;
  return (
    <button
      type="button"
      data-approval-header-action="true"
      onClick={() => navigate("/approval")}
      className={
        count > 0
          ? "rounded-md border border-danger/40 bg-danger/10 px-3 py-1.5 text-xs font-medium text-danger"
          : "rounded-md border border-line bg-surface px-3 py-1.5 text-xs font-medium text-muted hover:bg-canvas"
      }
    >
      {count > 0 ? `待审批 ${count} 单` : "出库审批"}
    </button>
  );
}

function ApprovalListBanner(props: InventoryListSlotProps) {
  const { policy, summary } = useApproval();
  if (props.items.length === 0) return null;
  return (
    <div
      data-approval-banner="true"
      className="mb-3 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-line bg-surface px-3 py-2 text-xs text-muted"
    >
      <span>
        出库审批：单次出库超过 <b className="text-ink">{policy.threshold}</b>{" "}
        件需填写审批理由，否则由审批插件拦截
      </span>
      <span className="text-[11px] opacity-80">
        待审批 {summary.pendingCount} 单 · 已拦截 {summary.blockedCount} 次
      </span>
    </div>
  );
}

function ApprovalItemBadge({ item }: InventoryItemSlotProps) {
  const { requests } = useApproval();
  const pending = useMemo(
    () =>
      requests.filter(
        (request) => request.itemId === item.id && request.status === "pending",
      ).length,
    [requests, item.id],
  );
  if (pending === 0) return null;
  return (
    <span
      data-approval-badge={item.sku}
      className="rounded border border-danger/40 bg-danger/10 px-1.5 py-0.5 text-[11px] font-medium text-danger"
    >
      待审批 {pending}
    </span>
  );
}

function SummaryCard(props: {
  readonly label: string;
  readonly value: number;
  readonly tone: string;
}) {
  return (
    <div className={`rounded-lg border px-3 py-2 ${props.tone}`}>
      <div className="text-[11px] opacity-80">{props.label}</div>
      <div className="font-mono text-lg font-semibold">{props.value}</div>
    </div>
  );
}

function ApprovalPage() {
  const navigate = useNavigate();
  const { policy, summary, requests, audit, loading, error, reload } =
    useApproval();

  const [items, setItems] = useState<InventoryItemSummary[]>([]);
  const [itemId, setItemId] = useState("");
  const [quantity, setQuantity] = useState("60");
  const [reason, setReason] = useState("");
  const [thresholdInput, setThresholdInput] = useState(String(policy.threshold));
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState("");
  const [hint, setHint] = useState("");

  const loadItems = useCallback(async () => {
    try {
      const data = await requestJson<{ items: InventoryItemSummary[] }>(
        "/api/app/inventory-core/items",
      );
      setItems(data.items ?? []);
    } catch {
      setItems([]);
    }
  }, []);

  useEffect(() => {
    void loadItems();
  }, [loadItems]);

  useEffect(() => {
    setThresholdInput(String(policy.threshold));
  }, [policy.threshold]);

  const pending = useMemo(
    () => requests.filter((request) => request.status === "pending"),
    [requests],
  );
  const selectedItem = items.find((item) => item.id === itemId);

  const submitRequest = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    if (!itemId) {
      setFormError("请选择需要出库的商品");
      return;
    }
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{ request: ApprovalRequestView }>(
        "/api/app/inventory-approval/requests",
        {
          method: "POST",
          body: JSON.stringify({
            itemId,
            quantity: Number(quantity) || 0,
            reason: reason.trim(),
          }),
        },
      );
      setReason("");
      setHint(`审批单 ${data.request.code} 已提交，等待审批`);
      await reload();
      await loadItems();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const approve = async (request: ApprovalRequestView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{
        request: ApprovalRequestView;
        item: InventoryItemSummary;
      }>(
        `/api/app/inventory-approval/requests/${encodeURIComponent(
          request.id,
        )}/approve`,
        { method: "POST", body: JSON.stringify({ approver: "出库审批工作台" }) },
      );
      setHint(
        `审批单 ${data.request.code} 已通过，出库 ${data.request.quantity} ${data.item.unit}`,
      );
      await reload();
      await loadItems();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const reject = async (request: ApprovalRequestView) => {
    if (busy) return;
    setBusy(true);
    setFormError("");
    setHint("");
    try {
      const data = await requestJson<{ request: ApprovalRequestView }>(
        `/api/app/inventory-approval/requests/${encodeURIComponent(
          request.id,
        )}/reject`,
        {
          method: "POST",
          body: JSON.stringify({ note: "出库审批工作台驳回" }),
        },
      );
      setHint(`审批单 ${data.request.code} 已驳回`);
