", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  ApprovalAuditEntry,
  ApprovalOutcome,
  ApprovalOverview,
  ApprovalPolicy,
  ApprovalRequestView,
  ApprovalSource,
  ApprovalStatus,
  ApprovalSummary,
  BeforeStockChangePayload,
  CreateApprovalRequestInput,
  InventoryApprovalService,
} from "./contract.d.ts";

const DEFAULT_THRESHOLD = 50;
const MIN_THRESHOLD = 1;
const MAX_THRESHOLD = 1_000_000;
const DEFAULT_AUDIT_LIMIT = 20;
const MAX_AUDIT_LIMIT = 100;
const APPROVAL_REASON_PATTERN = /^\[审批\s+([A-Za-z0-9-]+)\]/;

const REQUEST_COLUMNS =
  "id, code, item_id, item_sku, item_name, quantity, reason, status, note, decided_at, executed_quantity, created_at, updated_at";
const AUDIT_COLUMNS =
  "id, item_id, item_sku, delta, outbound_quantity, threshold, reason, outcome, source, approval_id, approval_code, created_at";

interface CoreInventoryItem {
  readonly id: string;
  readonly sku: string;
  readonly name: string;
  readonly quantity: number;
  readonly unit: string;
}

interface CoreInventoryService {
  list(): CoreInventoryItem[];
  get(id: string): CoreInventoryItem | null;
  adjustStock(
    id: string,
    delta: number,
    reason?: string,
  ): Promise<CoreInventoryItem>;
}

interface RequestRow {
  readonly id: string;
  readonly code: string;
  readonly item_id: string;
  readonly item_sku: string;
  readonly item_name: string;
  readonly quantity: number;
  readonly reason: string;
  readonly status: string;
  readonly note: string | null;
  readonly decided_at: string | null;
  readonly executed_quantity: number | null;
  readonly created_at: string;
  readonly updated_at: string;
}

interface AuditRow {
  readonly id: string;
  readonly item_id: string;
  readonly item_sku: string | null;
  readonly delta: number;
  readonly outbound_quantity: number;
  readonly threshold: number;
  readonly reason: string | null;
  readonly outcome: string;
  readonly source: string;
  readonly approval_id: string | null;
  readonly approval_code: string | null;
  readonly created_at: string;
}

interface SettingRow {
  readonly value: string;
  readonly updated_at: string;
}

interface AuditDraft {
  readonly itemId: string;
  readonly itemSku: string | null;
  readonly delta: number;
  readonly outboundQuantity: number;
  readonly threshold: number;
  readonly reason: string | null;
  readonly outcome: ApprovalOutcome;
  readonly source: ApprovalSource;
  readonly approvalId: string | null;
  readonly approvalCode: string | null;
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

function toErrorResponse(error: unknown): {
  status: number;
  body: { error: string };
} {
  const status =
    typeof (error as { status?: unknown })?.status === "number"
      ? (error as { status: number }).status
      : 400;
  return {
    status,
    body: { error: error instanceof Error ? error.message : String(error) },
  };
}

function makeId(prefix: string): string {
  return `${prefix}_${Date.now().toString(36)}_${Math.random()
    .toString(36)
    .slice(2, 8)}`;
}

function clampThreshold(value: number): number {
  if (!Number.isFinite(value)) return DEFAULT_THRESHOLD;
  return Math.min(MAX_THRESHOLD, Math.max(MIN_THRESHOLD, Math.trunc(value)));
}

function readLimit(raw: string | undefined): number {
  if (typeof raw !== "string" || raw.trim().length === 0) {
    return DEFAULT_AUDIT_LIMIT;
  }
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isFinite(parsed)) return DEFAULT_AUDIT_LIMIT;
  return Math.min(Math.max(1, parsed), MAX_AUDIT_LIMIT);
}

function coreInventory(ctx: Context): CoreInventoryService | undefined {
  return (ctx as unknown as { inventory?: CoreInventoryService }).inventory;
}

export default class InventoryApprovalServiceImpl
  extends Service
  implements InventoryApprovalService
{
  static inject = ["inventory"];

  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "inventoryApproval");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_inventory_approval__requests (
        id TEXT PRIMARY KEY,
        code TEXT NOT NULL UNIQUE,
        item_id TEXT NOT NULL,
        item_sku TEXT NOT NULL,
        item_name TEXT NOT NULL,
        quantity INTEGER NOT NULL,
        reason TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        note TEXT,
        decided_at TEXT,
        executed_quantity INTEGER,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      )
    `);
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS plg_inventory_approval__requests_status
      ON plg_inventory_approval__requests (status, created_at)
    `);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_inventory_approval__audit (
        id TEXT PRIMARY KEY,
        item_id TEXT NOT NULL,
        item_sku TEXT,
        delta INTEGER NOT NULL,
        outbound_quantity INTEGER NOT NULL,
        threshold INTEGER NOT NULL,
        reason TEXT,
        outcome TEXT NOT NULL,
        source TEXT NOT NULL,
        approval_id TEXT,
        approval_code TEXT,
        created_at TEXT NOT NULL
      )
    `);
    this.db.exec(`
      CREATE INDEX IF NOT EXISTS plg_inventory_approval__audit_created
      ON plg_inventory_approval__audit (created_at)
    `);
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_inventory_approval__settings (
        key TEXT PRIMARY KEY,
        value TEXT NOT NULL,
        updated_at TEXT NOT NULL
      )
    `);

    ctx.on("inventory:before-stock-change", (payload) =>
      this.beforeStockChange(payload),
    );

    ctx.http.route("GET", "/policy", () => ({ policy: this.getPolicy() }));

    ctx.http.route("PUT", "/policy", (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        if (
          typeof body.threshold !== "number" ||
          !Number.isFinite(body.threshold)
        ) {
          throw httpError(400, "Approval threshold must be a number");
        }
        return { policy: this.updatePolicy(body.threshold) };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("GET", "/requests", (req) => {
      const raw = req.query.status;
      const filter: ApprovalStatus | undefined =
        raw === "pending" || raw === "approved" || raw === "rejected"
          ? raw
          : undefined;
      return { requests: this.listRequests(filter), summary: this.summary() };
    });

    ctx.http.route("POST", "/requests", (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        const request = this.createRequest({
          itemId: typeof body.itemId === "string" ? body.itemId : "",
          quantity:
            typeof body.quantity === "number" ? body.quantity : Number.NaN,
          reason: typeof body.reason === "string" ? body.reason : "",
        });
        return { status: 201, body: { request } };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("POST", "/requests/:id/approve", async (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        const result = await this.approveRequest(
          req.params.id,
          typeof body.approver === "string" && body.approver.trim().length > 0
            ? body.approver.trim()
            : undefined,
        );
        return { request: result.request, item: result.item };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("POST", "/requests/:id/reject", (req) => {
      const body = (req.body ?? {}) as Record<string, unknown>;
      try {
        const request = this.rejectRequest(
          req.params.id,
          typeof body.note === "string" ? body.note : undefined,
        );
        return { request };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("GET", "/audit", (req) => ({
      entries: this.listAudit(readLimit(req.query.limit)),
    }));

    ctx.http.route("GET", "/overview", (req) =>
      this.overview(readLimit(req.query.limit)),
    );
  }

  getPolicy(): ApprovalPolicy {
    const row = this.db
      .prepare(
        `SELECT value, updated_at FROM plg_inventory_approval__settings WHERE key = 'threshold'`,
      )
      .get<SettingRow>();
    const threshold = row
      ? clampThreshold(Number.parseInt(row.value, 10))
      : DEFAULT_THRESHOLD;
    return { threshold, updatedAt: row?.updated_at ?? null };
  }

  updatePolicy(threshold: number): ApprovalPolicy {
    const value = Math.trunc(threshold);
    if (!Number.isFinite(value) || value < MIN_THRESHOLD || value > MAX_THRESHOLD) {
      throw httpError(
        400,
        `审批阈值必须是 ${MIN_THRESHOLD} 到 ${MAX_THRESHOLD} 之间的整数`,
      );
    }
    const now = new Date().toISOString();
    const existing = this.db
      .prepare(
        `SELECT key FROM plg_inventory_approval__settings WHERE key = 'threshold'`,
      )
      .get<{ key: string }>();
    if (existing) {
      this.db
        .prepare(
          `UPDATE plg_inventory_approval__settings SET value = ?, updated_at = ? WHERE key = 'threshold'`,
        )
        .run(String(value), now);
    } else {
      this.db
        .prepare(
          `INSERT INTO plg_inventory_approval__settings (key, value, updated_at) VALUES ('threshold', ?, ?)`,
        )
        .run(String(value), now);
    }
    return this.getPolicy();
  }

  listRequests(status?: ApprovalStatus): ApprovalRequestView[] {
    const rows = status
      ? this.db
          .prepare(
            `SELECT ${REQUEST_COLUMNS} FROM plg_inventory_approval__requests WHERE status = ? ORDER BY created_at DESC, id DESC`,
          )
          .all<RequestRow>(status)
      : this.db
          .prepare(
            `SELECT ${REQUEST_COLUMNS} FROM plg_inventory_approval__requests ORDER BY created_at DESC, id DESC`,
          )
          .all<RequestRow>();
    return rows.map((row) => this.toRequestView(row));
  }

  createRequest(input: CreateApprovalRequestInput): ApprovalRequestView {
    const inventory = coreInventory(this.ctx);
    const itemId = typeof input.itemId === "string" ? input.itemId.trim() : "";
    if (itemId.length === 0) throw httpError(400, "请选择需要出库的商品");
    const item = inventory?.get(itemId) ?? null;
    if (!item) throw httpError(404, `库存商品不存在: ${itemId}`);

    const quantity = Math.trunc(input.quantity);
    if (!Number.isFinite(quantity) || quantity <= 0) {
      throw httpError(400, "出库数量必须是正整数");
    }
    const reason = typeof input.reason === "string" ? input.reason.trim() : "";
    if (reason.length === 0) throw httpError(400, "必须填写审批理由");

    const policy = this.getPolicy();
    if (quantity <= policy.threshold) {
      throw httpError(
        400,
        `出库 ${quantity} 件未超过审批阈值 ${policy.threshold} 件，无需审批，请直接出库`,
      );
    }
    if (quantity > item.quantity) {
      throw httpError(
        409,
        `库存不足：${item.sku} 当前 ${item.quantity} 件，申请出库 ${quantity} 件`,
      );
    }

    const id = makeId("apv");
    const code = this.nextCode();
    const now = new Date().toISOString();
    this.db
      .prepare(
        `INSERT INTO plg_inventory_approval__requests
           (id, code, item_id, item_sku, item_name, quantity, reason, status, note, decided_at, executed_quantity, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', NULL, NULL, NULL, ?, ?)`,
      )
      .run(
        id,
        code,
        item.id,
        item.sku,
        item.name,
        quantity,
        reason,
        now,
        now,
      );
    return this.toRequestView(this.requestRowById(id)!);
  }

  async approveRequest(
    id: string,
    approver?: string,
  ): Promise<{ request: ApprovalRequestView; item: CoreInventoryItem }> {
    const row = this.requestRowById(id);
    if (!row) throw httpError(404, `审批单不存在: ${id}`);
    if (row.status !== "pending") {
      throw httpError(
        409,
        `审批单 ${row.code} 当前状态为 ${row.status}，无法重复审批`,
      );
    }

    const inventory = coreInventory(this.ctx);
    if (!inventory) throw httpError(503, "库存服务不可用，无法执行出库");
    const item = inventory.get(row.item_id);
    if (!item) throw httpError(404, `库存商品不存在: ${row.item_id}`);

    const quantity = Number(row.quantity);
    if (item.quantity < quantity) {
      throw httpError(
        409,
        `库存不足：${item.sku} 当前 ${item.quantity} 件，申请出库 ${quantity} 件`,
      );
    }

    const updated = await inventory.adjustStock(
      row.item_id,
      -Math.abs(quantity),
      `[审批 ${row.code}] ${row.reason}`,
    );

    const now = new Date().toISOString();
    const note =
      typeof approver === "string" && approver.trim().length > 0
        ? `审批人: ${approver.trim()}`
        : null;
    this.db
      .prepare(
        `UPDATE plg_inventory_approval__requests
         SET status = 'approved', note = ?, decided_at = ?, executed_quantity = ?, updated_at = ?
         WHERE id = ?`,
      )
      .run(note, now, quantity, now, id);

    return {
      request: this.toRequestView(this.requestRowById(id)!),
      item: updated,
    };
  }

  rejectRequest(id: string, note?: string): ApprovalRequestView {
    const row = this.requestRowById(id);
    if (!row) throw httpError(404, `审批单不存在: ${id}`);
    if (row.status !== "pending") {
      throw httpError(
        409,
        `审批单 ${row.code} 当前状态为 ${row.status}，无法重复审批`,
      );
    }
    const now = new Date().toISOString();
    const trimmed =
      typeof note === "string" && note.trim().length > 0 ? note.trim() : null;
    this.db
      .prepare(
        `UPDATE plg_inventory_approval__requests
         SET status = 'rejected', note = ?, decided_at = ?, updated_at = ?
         WHERE id = ?`,
      )
      .run(trimmed, now, now, id);
    return this.toRequestView(this.requestRowById(id)!);
  }

  summary(): ApprovalSummary {
    const statusCounts = new Map<string, number>();
    for (const row of this.db
      .prepare(
        `SELECT status, COUNT(*) AS total FROM plg_inventory_approval__requests GROUP BY status`,
      )
      .all<{ status: string; total: number }>()) {
      statusCounts.set(row.status, Number(row.total));
    }
    const outcomeCounts = new Map<string, number>();
    for (const row of this.db
      .prepare(
        `SELECT outcome, COUNT(*) AS total FROM plg_inventory_approval__audit GROUP BY outcome`,
      )
      .all<{ outcome: string; total: number }>()) {
      outcomeCounts.set(row.outcome, Number(row.total));
    }
    return {
      threshold: this.getPolicy().threshold,
      pendingCount: statusCounts.get("pending") ?? 0,
      approvedCount: statusCounts.get("approved") ?? 0,
      rejectedCount: statusCounts.get("rejected") ?? 0,
      blockedCount: outcomeCounts.get("blocked") ?? 0,
      allowedCount: outcomeCounts.get("allowed") ?? 0,
    };
  }

  listAudit(limit: number = DEFAULT_AUDIT_LIMIT): ApprovalAuditEntry[] {
    const size = Math.min(Math.max(1, Math.trunc(limit)), MAX_AUDIT_LIMIT);
    const rows = this.db
      .prepare(
        `SELECT ${AUDIT_COLUMNS} FROM plg_inventory_approval__audit ORDER BY created_at DESC, id DESC LIMIT ?`,
      )
      .all<AuditRow>(size);
    return rows.map((row) => this.toAuditEntry(row));
  }

  overview(limit: number = DEFAULT_AUDIT_LIMIT): ApprovalOverview {
    return {
      policy: this.getPolicy(),
      summary: this.summary(),
      requests: this.listRequests(),
      audit: this.listAudit(limit),
    };
  }

  /**
   * 库存变动前拦截：单次出库数量超过阈值时必须携带审批理由。
   * 返回字符串会作为 inventory-core 的 400 响应消息；返回 undefined 则放行。
   * 该监听器随插件卸载自动销毁，因此移除本插件后 inventory-core 恢复独立出库。
   */
  private beforeStockChange(
    payload: BeforeStockChangePayload,
  ): string | undefined {
    const delta = Number(payload?.delta ?? 0);
    if (!Number.isFinite(delta) || delta >= 0) return undefined;

    const outbound = Math.abs(Math.trunc(delta));
    let threshold = DEFAULT_THRESHOLD;
    try {
      threshold = this.getPolicy().threshold;
    } catch {
      threshold = DEFAULT_THRESHOLD;
    }
    if (outbound <= threshold) return undefined;

    const item = payload.item;
    const reason =
      typeof payload.reason === "string" ? payload.reason.trim() : "";
    const linked = reason.length > 0 ? this.findRequestByReason(reason) : undefined;

    this.recordAudit({
      itemId: item.id,
      itemSku: item.sku ?? null,
      delta: Math.trunc(delta),
      outboundQuantity: outbound,
      threshold,
      reason: reason.length > 0 ? reason : null,
      outcome: reason.length > 0 ? "allowed" : "blocked",
      source: linked ? "approval" : "direct",
      approvalId: linked?.id ?? null,
      approvalCode: linked?.code ?? null,
    });

    if (reason.length === 0) {
      return `单次出库 ${outbound} 件超过审批阈值 ${threshold} 件，请填写审批理由后重试`;
    }
    return undefined;
  }

  private findRequestByReason(
    reason: string,
  ): { id: string; code: string } | undefined {
    try {
      const match = APPROVAL_REASON_PATTERN.exec(reason);
      if (!match) return undefined;
      const row = this.db
        .prepare(
          `SELECT id, code FROM plg_inventory_approval__requests WHERE code = ?`,
        )
        .get<{ id: string; code: string }>(match[1]);
      return row ? { id: row.id, code: row.code } : undefined;
    } catch {
      return undefined;
    }
  }

  private recordAudit(draft: AuditDraft): void {
    try {
      this.db
        .prepare(
          `INSERT INTO plg_inventory_approval__audit
             (id, item_id, item_sku, delta, outbound_quantity, threshold, reason, outcome, source, approval_id, approval_code, created_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          makeId("apva"),
          draft.itemId,
          draft.itemSku,
          draft.delta,
          draft.outboundQuantity,
          draft.threshold,
          draft.reason,
          draft.outcome,
          draft.source,
          draft.approvalId,
          draft.approvalCode,
          new Date().toISOString(),
        );
    } catch {
      // 审计写入失败绝不能影响库存主流程
    }
  }

  private nextCode(): string {
    for (let attempt = 0; attempt < 5; attempt += 1) {
      const code = `APV-${Date.now().toString(36).toUpperCase().slice(-4)}${Math.random()
        .toString(36)
        .slice(2, 5)
        .toUpperCase()}`;
      const existing = this.db
        .prepare(
          `SELECT code FROM plg_inventory_approval__requests WHERE code = ?`,
        )
        .get<{ code: string }>(code);
      if (!existing) return code;
    }
    return `APV-${Date.now().toString(36).toUpperCase()}`;
  }

  private requestRowById(id: string): RequestRow | undefined {
    return this.db
      .prepare(
        `SELECT ${REQUEST_COLUMNS} FROM plg_inventory_approval__requests WHERE id = ?`,
      )
      .get<RequestRow>(id);
  }

  private toRequestView(row: RequestRow): ApprovalRequestView {
    const status: ApprovalStatus =
      row.status === "approved"
        ? "approved"
        : row.status === "rejected"
          ? "rejected"
          : "pending";
    return {
      id: row.id,
      code: row.code,
      itemId: row.item_id,
      itemSku: row.item_sku,
      itemName: row.item_name,
      quantity: Number(row.quantity),
      reason: row.reason,
      status,
      note: row.note ?? null,
      decidedAt: row.decided_at ?? null,
      executedQuantity:
        row.executed_quantity === null ? null : Number(row.executed_quantity),
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }

  private toAuditEntry(row: AuditRow): ApprovalAuditEntry {
    return {
      id: row.id,
      itemId: row.item_id,
      itemSku: row.item_sku ?? null,
      delta: Number(row.delta),
      outboundQuantity: Number(row.outbound_quantity),
      threshold: Number(row.threshold),
      reason: row.reason ?? null,
      outcome: row.outcome === "blocked" ? "blocked" : "allowed",
      source: row.source === "approval" ? "approval" : "direct",
      approvalId: row.approval_id ?? null,
      approvalCode: row.approval_code ?? null,
      createdAt: row.created_at,
    };
  }
}
