import type { PluginTestContext } from "@host/server-sdk";

interface ApprovalRequestView {
  readonly id: string;
  readonly code: string;
  readonly itemId: string;
  readonly itemSku: string;
  readonly quantity: number;
  readonly reason: string;
  readonly status: string;
  readonly note: string | null;
  readonly executedQuantity: number | null;
  readonly decidedAt: string | null;
}

interface ApprovalAuditEntry {
  readonly itemSku: string | null;
  readonly outboundQuantity: number;
  readonly threshold: number;
  readonly reason: string | null;
  readonly outcome: string;
  readonly source: string;
  readonly approvalCode: string | null;
}

interface ApprovalSummary {
  readonly threshold: number;
  readonly pendingCount: number;
  readonly approvedCount: number;
  readonly rejectedCount: number;
  readonly blockedCount: number;
  readonly allowedCount: number;
}

interface ApiResponse {
  readonly status: number;
  readonly body: unknown;
}

function expectStatus(
  response: ApiResponse,
  expected: number,
  label: string,
): void {
  assert.equal(
    response.status,
    expected,
    `${label} -> ${response.status}: ${JSON.stringify(response.body)}`,
  );
}

function errorMessage(response: ApiResponse): string {
  return String((response.body as { error?: string }).error ?? "");
}

function ourAudit(entries: readonly ApprovalAuditEntry[]): ApprovalAuditEntry[] {
  return entries.filter(
    (entry) => entry.itemSku === "APV-TEST-1" || entry.itemSku === "APV-TEST-2",
  );
}

async function itemQuantity(
  ctx: PluginTestContext,
  itemId: string,
): Promise<number> {
  const response = await ctx.request({
    method: "GET",
    path: `/api/app/inventory-core/items/${itemId}`,
  });
  expectStatus(response, 200, "read inventory item");
  return (response.body as { item: { quantity: number } }).item.quantity;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const createdA = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-core/items",
    body: { sku: "APV-TEST-1", name: "审批测试商品A", quantity: 120 },
  });
  expectStatus(createdA, 201, "create item A");
  const itemA = (createdA.body as { item: { id: string } }).item.id;

  const policy = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-approval/policy",
  });
  expectStatus(policy, 200, "read approval policy");
  assert.equal(
    (policy.body as { policy: { threshold: number } }).policy.threshold,
    50,
  );

  // 等于阈值（50 件）不属于“大于 50”，直接出库
  const smallOut = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemA}/stock`,
    body: { delta: -50 },
  });
  expectStatus(smallOut, 200, "outbound at threshold without reason");
  assert.equal(
    (smallOut.body as { item: { quantity: number } }).item.quantity,
    70,
  );

  // 51 件且没有审批理由 => 被拦截，库存不变
  const blocked = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemA}/stock`,
    body: { delta: -51 },
  });
  expectStatus(blocked, 400, "outbound above threshold without reason");
  assert.match(errorMessage(blocked), /审批理由/);
  assert.match(errorMessage(blocked), /50/);
  assert.equal(await itemQuantity(ctx, itemA), 70);

  // 空白理由不算填写审批理由
  const blankReason = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemA}/stock`,
    body: { delta: -51, reason: "   " },
  });
  expectStatus(blankReason, 400, "outbound above threshold with blank reason");
  assert.equal(await itemQuantity(ctx, itemA), 70);

  // 审批申请：理由必填
  const missingReason = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-approval/requests",
    body: { itemId: itemA, quantity: 60, reason: "   " },
  });
  expectStatus(missingReason, 400, "approval request without reason");

  // 未超过阈值无需审批
  const underThreshold = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-approval/requests",
    body: { itemId: itemA, quantity: 10, reason: "小单直出" },
  });
  expectStatus(underThreshold, 400, "approval request below threshold");

  // 超过现有库存 => 409
  const overStock = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-approval/requests",
    body: { itemId: itemA, quantity: 500, reason: "超量出库" },
  });
  expectStatus(overStock, 409, "approval request over stock");

  // 正常创建审批单
  const pendingRes = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-approval/requests",
    body: { itemId: itemA, quantity: 60, reason: "大客户整单出库" },
  });
  expectStatus(pendingRes, 201, "create approval request");
  const pending = (pendingRes.body as { request: ApprovalRequestView }).request;
  assert.equal(pending.status, "pending");
  assert.match(pending.code, /^APV-/);
  assert.equal(pending.quantity, 60);

  const missing = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-approval/requests/apv_missing/approve",
    body: {},
  });
  expectStatus(missing, 404, "approve unknown request");

  // 审批通过 => 由插件调用 inventory-core 完成出库
  const approvedRes = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-approval/requests/${pending.id}/approve`,
    body: { approver: "审批工作台" },
  });
  expectStatus(approvedRes, 200, "approve request");
  const approved = approvedRes.body as {
    request: ApprovalRequestView;
    item: { quantity: number };
  };
  assert.equal(approved.request.status, "approved");
  assert.equal(approved.request.executedQuantity, 60);
  assert.equal(approved.item.quantity, 10);
  assert.equal(await itemQuantity(ctx, itemA), 10);

  const repeat = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-approval/requests/${pending.id}/approve`,
    body: {},
  });
  expectStatus(repeat, 409, "approve twice");

  const createdB = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-core/items",
    body: { sku: "APV-TEST-2", name: "审批测试商品B", quantity: 120 },
  });
  expectStatus(createdB, 201, "create item B");
  const itemB = (createdB.body as { item: { id: string } }).item.id;

  // 携带审批理由的大额直接出库可放行，并留下 direct 审计
  const directOut = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemB}/stock`,
    body: { delta: -51, reason: "紧急调拨到门店" },
  });
  expectStatus(directOut, 200, "direct large outbound with reason");
  assert.equal(
    (directOut.body as { item: { quantity: number } }).item.quantity,
    69,
  );

  const pendingBRes = await ctx.request({
    method: "POST",
    path: "/api/app/inventory-approval/requests",
    body: { itemId: itemB, quantity: 51, reason: "门店补货" },
  });
  expectStatus(pendingBRes, 201, "create second approval request");
  const pendingB = (pendingBRes.body as { request: ApprovalRequestView }).request;

  const rejectedRes = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-approval/requests/${pendingB.id}/reject`,
    body: { note: "请拆单后重新提交" },
  });
  expectStatus(rejectedRes, 200, "reject request");
  const rejected = (rejectedRes.body as { request: ApprovalRequestView }).request;
  assert.equal(rejected.status, "rejected");
  assert.equal(rejected.note, "请拆单后重新提交");
  assert.equal(await itemQuantity(ctx, itemB), 69);

  const overviewRes = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-approval/overview",
  });
  expectStatus(overviewRes, 200, "approval overview");
  const overview = overviewRes.body as {
    policy: { threshold: number };
    summary: ApprovalSummary;
    requests: ApprovalRequestView[];
    audit: ApprovalAuditEntry[];
  };
  assert.equal(overview.policy.threshold, 50);
  assert.equal(
    overview.summary.pendingCount,
    overview.requests.filter((request) => request.status === "pending").length,
  );
  assert.equal(
    overview.summary.approvedCount,
    overview.requests.filter((request) => request.status === "approved").length,
  );
  assert.equal(
    overview.summary.rejectedCount,
    overview.requests.filter((request) => request.status === "rejected").length,
  );

  // 此刻 2 次拦截（无理由 / 空白理由）+ 2 次放行（审批单 / 直接出库）
  const snapshotAudit = ourAudit(overview.audit);
  const blockedEntries = snapshotAudit.filter(
    (entry) => entry.outcome === "blocked",
  );
  assert.equal(blockedEntries.length, 2);
  assert.ok(blockedEntries.every((entry) => entry.reason === null));
  assert.ok(
    blockedEntries.some(
      (entry) => entry.threshold === 50 && entry.outboundQuantity === 51,
    ),
  );
  assert.equal(
    snapshotAudit.filter((entry) => entry.outcome === "allowed").length,
    2,
  );
  const approvalAudit = snapshotAudit.filter(
    (entry) => entry.source === "approval",
  );
  assert.equal(approvalAudit.length, 1);
  assert.equal(approvalAudit[0].approvalCode, pending.code);
  assert.ok(approvalAudit[0].reason?.includes("大客户整单出库"));

  // 审批阈值可配置，拦截规则实时生效
  const tighten = await ctx.request({
    method: "PUT",
    path: "/api/app/inventory-approval/policy",
    body: { threshold: 5 },
  });
  expectStatus(tighten, 200, "tighten approval threshold");
  assert.equal(
    (tighten.body as { policy: { threshold: number } }).policy.threshold,
    5,
  );

  const blockedTight = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemA}/stock`,
    body: { delta: -6 },
  });
  expectStatus(blockedTight, 400, "outbound blocked under tightened threshold");
  assert.match(errorMessage(blockedTight), /审批理由/);
  assert.equal(await itemQuantity(ctx, itemA), 10);

  const restore = await ctx.request({
    method: "PUT",
    path: "/api/app/inventory-approval/policy",
    body: { threshold: 50 },
  });
  expectStatus(restore, 200, "restore approval threshold");
  assert.equal(
    (restore.body as { policy: { threshold: number } }).policy.threshold,
    50,
  );

  const allowedAfterRestore = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemA}/stock`,
    body: { delta: -6 },
  });
  expectStatus(allowedAfterRestore, 200, "outbound allowed after restore");
  assert.equal(
    (allowedAfterRestore.body as { item: { quantity: number } }).item.quantity,
    4,
  );

  const auditRes = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-approval/audit",
    query: { limit: "50" },
  });
  expectStatus(auditRes, 200, "approval audit trail");
  const finalAudit = ourAudit(
    (auditRes.body as { entries: ApprovalAuditEntry[] }).entries,
  );
  assert.equal(
    finalAudit.filter((entry) => entry.outcome === "blocked").length,
    3,
  );
  assert.equal(
