import { useCallback, useEffect, useMemo, useState, type FormEvent } from "react";
import type { Context } from "cordis";
import { useNavigate } from "@host/client-sdk";
import type {
  ExpiryBatchView,
  ExpiryOverview,
  ExpiryStatus,
  ExpirySummary,
} from "./contract.d.ts";

interface InventoryItemSummary {
  readonly id: string;
  readonly sku: string;
  readonly name: string;
  readonly quantity: number;
  readonly unit: string;
}

interface InventoryListSlotProps {
  readonly items: readonly InventoryItemSummary[];
  readonly refresh: () => Promise<void>;
}

interface InventoryItemSlotProps {
  readonly item: InventoryItemSummary;
  readonly refresh: () => Promise<void>;
}

const WINDOW_OPTIONS: readonly number[] = [7, 30, 90];

const EMPTY_SUMMARY: ExpirySummary = {
  windowDays: 30,
  criticalDays: 7,
  expiredCount: 0,
  criticalCount: 0,
  warningCount: 0,
  nearExpiryCount: 0,
  trackedBatchCount: 0,
  trackedQuantity: 0,
};

interface ExpirySnapshot {
  readonly windowDays: number;
  readonly summary: ExpirySummary;
  readonly alerts: readonly ExpiryBatchView[];
  readonly batches: readonly ExpiryBatchView[];
  readonly loading: boolean;
  readonly error: string;
}

let snapshot: ExpirySnapshot = {
  windowDays: 30,
  summary: EMPTY_SUMMARY,
  alerts: [],
  batches: [],
  loading: false,
  error: "",
};

const listeners = new Set<(next: ExpirySnapshot) => void>();
let inflight: Promise<void> | null = null;
let loadedWindow: number | null = null;

function publish(patch: Partial<ExpirySnapshot>): void {
  snapshot = { ...snapshot, ...patch };
  for (const listener of listeners) listener(snapshot);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data: Record<string, unknown> = text
    ? (JSON.parse(text) as Record<string, unknown>)
    : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

async function loadSnapshot(windowDays: number): Promise<void> {
  publish({ loading: true });
  try {
    const data = await requestJson<ExpiryOverview>(
      `/api/app/inventory-expiry/overview?windowDays=${windowDays}`,
    );
    loadedWindow = windowDays;
    publish({
      windowDays,
      summary: data.summary ?? EMPTY_SUMMARY,
      alerts: data.alerts ?? [],
      batches: data.batches ?? [],
      loading: false,
      error: "",
    });
  } catch (err) {
    loadedWindow = null;
    publish({
      loading: false,
      error: err instanceof Error ? err.message : String(err),
    });
  }
}

function refreshExpiry(windowDays: number, force = false): Promise<void> {
  if (inflight) return inflight;
  if (!force && loadedWindow === windowDays) return Promise.resolve();
  const promise = loadSnapshot(windowDays).finally(() => {
    inflight = null;
  });
  inflight = promise;
  return promise;
}

function useExpiry(windowDays = 30) {
  const [state, setState] = useState<ExpirySnapshot>(snapshot);

  useEffect(() => {
    const listener = (next: ExpirySnapshot) => setState(next);
    listeners.add(listener);
    setState(snapshot);
    void refreshExpiry(windowDays);
    return () => {
      listeners.delete(listener);
    };
  }, [windowDays]);

  const reload = useCallback(
    () => refreshExpiry(windowDays, true),
    [windowDays],
  );

  return {
    summary: state.summary,
    alerts: state.alerts,
    batches: state.batches,
    loading: state.loading,
    error: state.error,
    reload,
  };
}

function isoDateFromToday(offsetDays: number): string {
  const now = new Date();
  const target = new Date(
    Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + offsetDays),
  );
  return target.toISOString().slice(0, 10);
}

function formatDays(days: number): string {
  if (days < 0) return `已过期 ${Math.abs(days)} 天`;
  if (days === 0) return "今日到期";
  return `${days} 天后到期`;
}

function statusLabel(status: ExpiryStatus): string {
  switch (status) {
    case "expired":
      return "已过期";
    case "critical":
      return "紧急";
    case "warning":
      return "临近";
    default:
      return "正常";
  }
}

function statusTone(status: ExpiryStatus): string {
  switch (status) {
    case "expired":
      return "border-danger/40 bg-danger/10 text-danger";
    case "critical":
      return "border-danger/40 bg-canvas text-danger";
    case "warning":
      return "border-line bg-canvas text-ink";
    default:
      return "border-line bg-canvas text-muted";
  }
}

function ExpiryHeaderAction() {
  const navigate = useNavigate();
  const { summary } = useExpiry(30);
  const count = summary.nearExpiryCount;
  return (
    <button
      type="button"
      data-expiry-header-action="true"
      onClick={() => navigate("/expiry")}
      className={
        count > 0
          ? "rounded-md border border-danger/40 bg-danger/10 px-3 py-1.5 text-xs font-medium text-danger"
          : "rounded-md border border-line bg-surface px-3 py-1.5 text-xs font-medium text-muted hover:bg-canvas"
      }
    >
      {count > 0 ? `⚠ ${count} 项临期` : "效期台账"}
    </button>
  );
}

function ExpiryListBanner(props: InventoryListSlotProps) {
  const { summary, alerts } = useExpiry(30);
  if (props.items.length === 0 || summary.nearExpiryCount === 0) return null;
  const top = alerts.slice(0, 3);
  return (
    <div
      data-expiry-banner="true"
      className="mb-3 rounded-lg border border-danger/40 bg-danger/10 px-3 py-2 text-xs text-danger"
    >
      <div className="flex flex-wrap items-center justify-between gap-2">
        <span className="font-semibold">
          效期预警：{summary.expiredCount} 批已过期 ·{" "}
          {summary.criticalCount + summary.warningCount} 批临期
        </span>
        <span className="text-[11px] opacity-80">
          过期批次请先核销，再处理出库
        </span>
      </div>
      <ul className="mt-1.5 space-y-0.5">
        {top.map((alert) => (
          <li key={alert.id} data-expiry-banner-item={alert.batchNo}>
            {alert.itemSku ?? alert.itemId} · 批次 {alert.batchNo} ·{" "}
            {formatDays(alert.daysUntilExpiry)} · 余 {alert.quantity}
          </li>
        ))}
      </ul>
    </div>
  );
}

function ExpiryItemBadges({ item }: InventoryItemSlotProps) {
  const { batches } = useExpiry(30);
  const mine = useMemo(
    () =>
      batches.filter(
        (batch) => batch.itemId === item.id && batch.quantity > 0,
      ),
    [batches, item.id],
  );
  if (mine.length === 0) return null;
  const nearest = mine.reduce(
    (acc, batch) => (batch.daysUntilExpiry < acc.daysUntilExpiry ? batch : acc),
    mine[0],
  );
  return (
    <span
      data-expiry-badge={item.sku}
      className={`rounded border px-1.5 py-0.5 text-[11px] font-medium ${statusTone(
        nearest.status,
      )}`}
    >
      {nearest.status === "ok"
        ? `效期 ${nearest.expiryDate}`
        : `${statusLabel(nearest.status)} · ${formatDays(nearest.daysUntilExpiry)}`}
    </span>
  );
}

function ExpiryItemDetail({ item }: InventoryItemSlotProps) {
  const { batches, reload } = useExpiry(30);
  const [open, setOpen] = useState(false);
  const [batchNo, setBatchNo] = useState("");
  const [quantity, setQuantity] = useState("10");
  const [expiryDate, setExpiryDate] = useState(() => isoDateFromToday(90));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const mine = useMemo(
    () => batches.filter((batch) => batch.itemId === item.id),
    [batches, item.id],
  );
  const registered = mine.reduce((sum, batch) => sum + batch.quantity, 0);
  const uncovered = Math.max(0, item.quantity - registered);

  const submit = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await requestJson<{ batch: ExpiryBatchView }>(
        "/api/app/inventory-expiry/batches",
        {
          method: "POST",
          body: JSON.stringify({
            itemId: item.id,
            batchNo: batchNo.trim(),
            quantity: Number(quantity) || 0,
            expiryDate,
          }),
        },
      );
      setBatchNo("");
      setOpen(false);
      await reload();
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      data-expiry-detail={item.sku}
      className="mt-2 border-t border-line pt-2 text-xs text-muted"
    >
      <div className="flex flex-wrap items-center gap-2">
        <span>
          效期批次 {mine.length} 个 · 已登记 {registered} {item.unit} · 未登记{" "}
          {uncovered} {item.unit}
        </span>
        <button
          type="button"
          data-expiry-toggle={item.sku}
          onClick={() => setOpen((prev) => !prev)}
          className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] font-medium text-ink hover:bg-line/40"
        >
          {open ? "收起效期登记" : "登记效期批次"}
        </button>
      </div>

      {mine.length > 0 && (
        <ul className="mt-1.5 space-y-1">
          {mine.map((batch) => (
            <li
              key={batch.id}
              data-expiry-row={batch.batchNo}
              className="flex flex-wrap items-center gap-2"
            >
              <span className="font-mono text-ink">{batch.batchNo}</span>
              <span>余 {batch.quantity}</span>
              <span>{batch.expiryDate}</span>
              <span
                className={`rounded border px-1.5 py-0.5 text-[11px] ${statusTone(
                  batch.status,
                )}`}
              >
                {statusLabel(batch.status)} · {formatDays(batch.daysUntilExpiry)}
              </span>
            </li>
          ))}
        </ul>
      )}

      {open && (
        <form
          onSubmit={(event) => void submit(event)}
          data-expiry-form={item.sku}
          className="mt-2 flex flex-wrap items-center gap-2"
        >
          <input
            type="text"
            value={batchNo}
            onChange={(e) => setBatchNo(e.target.value)}
            placeholder="批次号"
            data-expiry-batch-input={item.sku}
            className="w-28 rounded border border-line bg-canvas px-2 py-1 text-xs text-ink"
          />
          <input
            type="number"
            min={1}
            value={quantity}
            onChange={(e) => setQuantity(e.target.value)}
            placeholder="数量"
            data-expiry-qty-input={item.sku}
            className="w-20 rounded border border-line bg-canvas px-2 py-1 text-xs text-ink"
          />
          <input
            type="date"
            value={expiryDate}
            onChange={(e) => setExpiryDate(e.target.value)}
            data-expiry-date-input={item.sku}
            className="rounded border border-line bg-canvas px-2 py-1 text-xs text-ink"
          />
          <button
            type="submit"
            disabled={busy}
            data-expiry-submit={item.sku}
            className="rounded-md bg-accent px-2.5 py-1 text-xs font-medium text-surface disabled:opacity-50"
          >
            保存批次
          </button>
          {error && (
            <span role="alert" className="text-danger">
              {error}
            </span>
          )}
        </form>
      )}
    </div>
  );
}

function SummaryCard(props: {
  readonly label: string;
  readonly value: number;
  readonly tone: string;
}) {
  return (
    <div className={`rounded-lg border px-3 py-2 ${props.tone}`}>
      <div className="text-[11px] opacity-80">{props.label}</div>
      <div className="font-mono text-lg font-semibold">{props.value}</div>
    </div>
  );
}

function ExpiryDashboardPage() {
  const navigate = useNavigate();
  const [windowDays, setWindowDays] = useState(30);
  const [items, setItems] = useState<InventoryItemSummary[]>([]);
  const [itemId, setItemId] = useState("");
  const [batchNo, setBatchNo] = useState("");
  const [quantity, setQuantity] = useState("10");
  const [expiryDate, setExpiryDate] = useState(() => isoDateFromToday(90));
  const [busy, setBusy] = useState(false);
  const [formError, setFormError] = useState("");
  const [formHint, setFormHint] = useState("");

  const { summary, alerts, loading, error, reload } = useExpiry(windowDays);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const data = await requestJson<{ items: InventoryItemSummary[] }>(
          "/api/app/inventory-core/items",
        );
        if (!cancelled) setItems(data.items ?? []);
      } catch {
        if (!cancelled) setItems([]);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const selectedItem = items.find((item) => item.id === itemId);

  const submitRegister = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    if (!itemId) {
      setFormError("请选择商品");
      return;
    }
    setBusy(true);
    setFormError("");
    setFormHint("");
    try {
      await requestJson<{ batch: ExpiryBatchView }>(
        "/api/app/inventory-expiry/batches",
        {
          method: "POST",
          body: JSON.stringify({
            itemId,
            batchNo: batchNo.trim(),
            quantity: Number(quantity) || 0,
            expiryDate,
          }),
        },
      );
      setBatchNo("");
      setFormHint("批次效期已登记");
      await reload();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const writeOff = async (batch: ExpiryBatchView) => {
    setBusy(true);
    setFormError("");
    setFormHint("");
    try {
      await requestJson<{ batch: ExpiryBatchView }>(
        `/api/app/inventory-expiry/batches/${encodeURIComponent(
          batch.id,
        )}/write-off`,
        { method: "POST", body: JSON.stringify({ reason: "过期核销" }) },
      );
      setFormHint(`批次 ${batch.batchNo} 已核销`);
      await reload();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  const removeBatch = async (batch: ExpiryBatchView) => {
    setBusy(true);
    setFormError("");
    setFormHint("");
    try {
      await requestJson<{ deleted: boolean }>(
        `/api/app/inventory-expiry/batches/${encodeURIComponent(batch.id)}`,
        { method: "DELETE" },
      );
      setFormHint(`批次 ${batch.batchNo} 已删除`);
      await reload();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : String(err));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div data-expiry-page="true" className="mx-auto max-w-4xl p-6 text-ink">
      <header className="mb-4 flex flex-wrap items-center justify-between gap-3 border-b border-line pb-3">
        <div>
          <h1 className="text-lg font-semibold">效期台账与临期预警</h1>
          <p className="text-xs text-muted">
            按批次登记生产效期，自动汇总过期 / 临期库存
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {WINDOW_OPTIONS.map((option) => (
            <button
              key={option}
              type="button"
              data-expiry-window={option}
              onClick={() => setWindowDays(option)}
              className={
                option === windowDays
                  ? "rounded-md border border-line bg-canvas px-2.5 py-1 text-xs font-medium text-ink"
                  : "rounded-md border border-line bg-surface px-2.5 py-1 text-xs font-medium text-muted hover:bg-canvas"
              }
            >
              {option} 天
            </button>
          ))}
          <button
            type="button"
            data-expiry-back="true"
            onClick={() => navigate("/")}
            className="rounded-md border border-line bg-surface px-3 py-1.5 text-xs font-medium text-ink hover:bg-canvas"
          >
            返回库存
          </button>
        </div>
      </header>

      {error && (
        <div
          role="alert"
          data-expiry-error="true"
          className="mb-3 rounded-md border border-danger/40 bg-danger/10 px-3 py-2 text-xs text-danger"
        >
          {error}
        </div>
      )}

      <div className="mb-4 grid grid-cols-2 gap-2 sm:grid-cols-4">
        <SummaryCard
          label="已过期批次"
          value={summary.expiredCount}
          tone="border-danger/40 bg-danger/10 text-danger"
        />
        <SummaryCard
          label={`${summary.criticalDays} 天内到期`}
          value={summary.criticalCount}
          tone="border-danger/40 bg-surface text-danger"
        />
        <SummaryCard
          label={`${summary.windowDays} 天内到期`}
          value={summary.warningCount}
          tone="border-line bg-surface text-ink"
        />
        <SummaryCard
          label={`在册批次 / ${summary.trackedQuantity} 件`}
          value={summary.trackedBatchCount}
          tone="border-line bg-surface text-muted"
        />
      </div>

      <section className="rounded-lg border border-line bg-surface">
        <div className="flex flex-wrap items-center justify-between gap-2 border-b border-line px-3 py-2">
          <h2 className="text-sm font-semibold">临期与过期批次</h2>
          <span className="text-xs text-muted">
            窗口 {summary.windowDays} 天 · 紧急阈值 {summary.criticalDays} 天
          </span>
        </div>
        {loading ? (
          <div className="py-6 text-center text-xs text-muted">加载效期数据…</div>
        ) : alerts.length === 0 ? (
          <div className="py-6 text-center text-xs text-muted">
            当前窗口内没有临期批次
          </div>
        ) : (
          <table className="w-full text-left text-xs" data-expiry-table="true">
            <thead className="bg-canvas text-muted">
              <tr>
                <th className="px-3 py-1.5 font-medium">商品</th>
                <th className="px-3 py-1.5 font-medium">批次</th>
                <th className="px-3 py-1.5 font-medium">数量</th>
                <th className="px-3 py-1.5 font-medium">效期</th>
                <th className="px-3 py-1.5 font-medium">状态</th>
                <th className="px-3 py-1.5 font-medium">操作</th>
              </tr>
            </thead>
            <tbody>
              {alerts.map((batch) => (
                <tr
                  key={batch.id}
                  data-expiry-alert-row={batch.batchNo}
                  className="border-t border-line"
                >
                  <td className="px-3 py-1.5">
                    <span className="font-mono text-muted">
                      {batch.itemSku ?? "-"}
                    </span>{" "}
                    {batch.itemName ?? ""}
                  </td>
                  <td className="px-3 py-1.5 font-mono">{batch.batchNo}</td>
                  <td className="px-3 py-1.5">{batch.quantity}</td>
                  <td className="px-3 py-1.5">{batch.expiryDate}</td>
                  <td className="px-3 py-1.5">
                    <span
                      className={`rounded border px-1.5 py-0.5 text-[11px] ${statusTone(
                        batch.status,
                      )}`}
                    >
                      {statusLabel(batch.status)} ·{" "}
                      {formatDays(batch.daysUntilExpiry)}
                    </span>
                  </td>
                  <td className="px-3 py-1.5">
                    <div className="flex items-center gap-1.5">
                      <button
                        type="button"
                        disabled={busy}
                        data-expiry-writeoff={batch.batchNo}
                        onClick={() => void writeOff(batch)}
                        className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] hover:bg-line/40 disabled:opacity-50"
                      >
                        核销
                      </button>
                      <button
                        type="button"
                        disabled={busy}
                        data-expiry-delete={batch.batchNo}
                        onClick={() => void removeBatch(batch)}
                        className="rounded border border-line bg-canvas px-2 py-0.5 text-[11px] hover:bg-line/40 disabled:opacity-50"
                      >
                        删除
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="mt-4 rounded-lg border border-line bg-surface p-3">
        <h2 className="mb-2 text-sm font-semibold">登记批次效期</h2>
        {items.length === 0 ? (
          <p className="text-xs text-muted">
            暂无商品，请先在库存页新增商品后再登记效期。
          </p>
        ) : (
          <form
            onSubmit={(event) => void submitRegister(event)}
            data-expiry-register-form="true"
            className="flex flex-wrap items-center gap-2"
          >
            <select
              value={itemId}
              onChange={(e) => setItemId(e.target.value)}
              data-expiry-item-select="true"
              className="rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            >
              <option value="">选择商品</option>
              {items.map((item) => (
                <option key={item.id} value={item.id}>
                  {item.sku} · {item.name} · 库存 {item.quantity}
                </option>
              ))}
            </select>
            <input
              type="text"
              value={batchNo}
              onChange={(e) => setBatchNo(e.target.value)}
              placeholder="批次号"
              data-expiry-batch-input="true"
              className="w-28 rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            />
            <input
              type="number"
              min={1}
              value={quantity}
              onChange={(e) => setQuantity(e.target.value)}
              placeholder="数量"
              data-expiry-qty-input="true"
              className="w-20 rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            />
            <input
              type="date"
              value={expiryDate}
              onChange={(e) => setExpiryDate(e.target.value)}
              data-expiry-date-input="true"
              className="rounded border border-line bg-canvas px-2 py-1.5 text-xs text-ink"
            />
            <button
              type="submit"
              disabled={busy}
              data-expiry-register-submit="true"
              className="rounded-md bg-accent px-3 py-1.5 text-xs font-medium text-surface hover:bg-accent/90 disabled:opacity-50"
            >
              登记批次
            </button>
            {selectedItem && (
              <span className="text-xs text-muted">
                当前库存 {selectedItem.quantity} {selectedItem.unit}
              </span>
            )}
            {formError && (
              <span role="alert" className="text-xs text-danger">
                {formError}
              </span>
            )}
            {formHint && <span className="text-xs text-muted">{formHint}</span>}
          </form>
        )}
      </section>
    </div>
  );
}

