                  </td>
                  <td className="px-3 py-1.5">
                    {entry.source === "approval"
                      ? `审批单 ${entry.approvalCode ?? ""}`
                      : "直接出库"}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </section>

      <section className="mt-4 rounded-lg border border-line bg-surface">
        <div className="border-b border-line px-3 py-2">
          <h2 className="text-sm font-semibold">最近审批单</h2>
        </div>
        {requests.length === 0 ? (
          <div className="py-6 text-center text-xs text-muted">暂无审批单</div>
        ) : (
          <ul className="divide-y divide-line text-xs">
            {requests.slice(0, 8).map((request) => (
              <li
                key={request.id}
                data-approval-history-row={request.code}
                className="flex flex-wrap items-center gap-2 px-3 py-1.5"
              >
                <span className="font-mono text-muted">{request.code}</span>
                <span>{request.itemSku}</span>
                <span>{request.quantity} 件</span>
                <span
                  className={`rounded border px-1.5 py-0.5 text-[11px] ${statusTone(
                    request.status,
                  )}`}
                >
                  {statusLabel(request.status)}
                </span>
                {request.note && (
                  <span className="text-muted">{request.note}</span>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

