  );

  const allowedAfterRestore = await ctx.request({
    method: "POST",
    path: `/api/app/inventory-core/items/${itemA}/stock`,
    body: { delta: -6 },
  });
  expectStatus(allowedAfterRestore, 200, "outbound allowed after restore");
  assert.equal(
    (allowedAfterRestore.body as { item: { quantity: number } }).item.quantity,
    4,
  );

  // 审计只记录“超过阈值”的出库尝试：3 次拦截 + 2 次放行
  const auditRes = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-approval/audit",
    query: { limit: "50" },
  });
  expectStatus(auditRes, 200, "approval audit trail");
  const finalAudit = ourAudit(
    (auditRes.body as { entries: ApprovalAuditEntry[] }).entries,
  );
  assert.equal(
    finalAudit.filter((entry) => entry.outcome === "blocked").length,
    3,
  );
  assert.equal(
    finalAudit.filter((entry) => entry.outcome === "allowed").length,
    2,
  );
  assert.ok(
    finalAudit.some(
      (entry) => entry.threshold === 5 && entry.outboundQuantity === 6,
    ),
  );

  // inventory-core 始终是唯一库存真相
  const itemsRes = await ctx.request({
    method: "GET",
    path: "/api/app/inventory-core/items",
  });
  expectStatus(itemsRes, 200, "list inventory items");
  const items = (itemsRes.body as { items: { sku: string; quantity: number }[] })
    .items;
  assert.equal(items.find((item) => item.sku === "APV-TEST-1")?.quantity, 4);
  assert.equal(items.find((item) => item.sku === "APV-TEST-2")?.quantity, 69);
}
